class SkillLibrary:
    def __init__(self, chroma_client):
        self.skills = {}  # name -> executable code
        self.metadata = {}  # name -> {description, success_rate, usage_count}
        self.chroma = chroma_client

    def add_skill(self, name: str, code: str, description: str):
        """Add verified skill to library"""
        self.skills[name] = code
        self.metadata[name] = {
            'description': description,
            'success_rate': 1.0,
            'usage_count': 0,
            'created_at': datetime.now()
        }
        # Index for retrieval
        self.chroma.add_document(
            id=f'skill_{name}',
            text=description,
            metadata={'skill_name': name}
        )

    def retrieve(self, task_description: str, k: int = 3):
        """Retrieve relevant skills by semantic similarity"""
        results = self.chroma.query(
            query_texts=[task_description],
            n_results=k
        )
        return [r['metadata']['skill_name'] for r in results]

    def execute(self, skill_name: str, **kwargs):
        """Execute skill with given arguments"""
        if skill_name not in self.skills:
            raise ValueError(f'Skill {skill_name} not found')

        # Track usage
        self.metadata[skill_name]['usage_count'] += 1

        # Execute
        code = self.skills[skill_name]
        return self._run_in_sandbox(code, kwargs)

    def compose(self, skills: List[str]):
        """Compose multiple skills into workflow"""
        return ComposedSkill([self.skills[s] for s in skills])
