class EveOrchestrator:
    """Coordinates multi-agent workflow"""
    def __init__(self):
        self.agents = {
            'researcher': EveResearcher(),
            'architect': EveArchitect(),
            'coder': EveCoder(),
            'reviewer': EveReviewer()
